package com.cyancoder.report.entity;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="platform_health_run",indexes=@Index(name="idx_platform_health_scope",columnList="tenant_key,site_key,created_at"))public class PlatformHealthRunEntity{@Id@Column(name="run_id",length=64)private String runId;@Column(name="tenant_key",nullable=false,length=100)private String tenantKey;@Column(name="site_key",length=100)private String siteKey;@Column(nullable=false,length=180)private String actor;@Column(nullable=false,length=24)private String status;@Lob@Column(name="checks_json",nullable=false)private String checksJson;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="completed_at",nullable=false)private Instant completedAt;public String getRunId(){return runId;}public void setRunId(String v){runId=v;}public String getTenantKey(){return tenantKey;}public void setTenantKey(String v){tenantKey=v;}public String getSiteKey(){return siteKey;}public void setSiteKey(String v){siteKey=v;}public String getActor(){return actor;}public void setActor(String v){actor=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getChecksJson(){return checksJson;}public void setChecksJson(String v){checksJson=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getCompletedAt(){return completedAt;}public void setCompletedAt(Instant v){completedAt=v;}}
